import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,x as n,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"利用這個 USB ID 倉庫識別更多 Linux 上的設備 | LCTT x X-CMD","titleTemplate":false,"description":"利用這個 USB ID 倉庫識別更多 Linux 上的設備 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"利用這個 USB ID 倉庫識別更多 Linux 上的設備 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"利用這個 USB ID 倉庫識別更多 Linux 上的設備 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200824 Recognize more devices on Linux with this USB ID Repository","title":"利用這個 USB ID 倉庫識別更多 Linux 上的設備","tag":"202009","desc":""},"relativePath":"202009/20200824 Recognize more devices on Linux with this USB ID Repository.md","filePath":"[post].md"}'),c={name:"202009/20200824 Recognize more devices on Linux with this USB ID Repository.md"};function u(b,s,h,g,f,D){const a=o("Link");return r(),d("div",null,[s[20]||(s[20]=l(`<h1 id="利用這個-usb-id-倉庫識別更多-linux-上的設備" tabindex="-1">利用這個 USB ID 倉庫識別更多 Linux 上的設備 <a class="header-anchor" href="#利用這個-usb-id-倉庫識別更多-linux-上的設備" aria-label="Permalink to “利用這個 USB ID 倉庫識別更多 Linux 上的設備”">​</a></h1><blockquote><p>這是一個包含了所有已知 USB 設備 ID 的開源項目。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202009/13/225426zpfbfopxhjxomuxf.jpg" alt=""></p><p>市場上有成千上萬的 USB 設備：鍵盤、掃描儀、打印機、鼠標和其他無數的設備，都能在 Linux 上工作。它們的供應商詳情都存儲在 USB ID 倉庫中。</p><h3 id="lsusb" tabindex="-1">lsusb <a class="header-anchor" href="#lsusb" aria-label="Permalink to “lsusb”">​</a></h3><p>Linux <code>lsusb</code> 命令列出了連接到系統的 USB 設備的信息，但有時信息不完整。例如，我最近注意到我的一個 USB 設備的品牌沒有被識別。設備是可以使用的，但是在列出我所連接的 USB 設備的詳情中沒有提供任何識別信息。以下是我的 <code>lsusb</code> 命令的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 004: ID 046d:082c Logitech, Inc.</span></span>
<span class="line"><span>Bus 001 Device 003: ID 0951:16d2 Kingston Technology</span></span>
<span class="line"><span>Bus 001 Device 002: ID 18f8:1486  </span></span>
<span class="line"><span>Bus 001 Device 005: ID 051d:0002 American Power Conversion Uninterruptible Power Supply</span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span></code></pre></div><p>正如你在最後一欄中看到的，有一個設備沒有製造商描述。要確定這個設備是什麼，我必須對我的 USB 設備樹進行更深入的檢查。幸運的是，<code>lsusb</code> 命令有更多的選項。其中一個選項是 <code>-D device</code>，來獲取每個設備的詳細信息，正如手冊頁面所解釋的那樣：</p><blockquote><p>“不會掃描 <code>/dev/bus/usb</code> 目錄，而只顯示給定設備文件所屬設備的信息。設備文件應該是類似 <code>/dev/bus/usb/001/001</code> 這樣的文件。這個選項會像 <code>v</code> 選項一樣顯示詳細信息，但你必須是 root 用户才行。&quot;</p></blockquote><p>我認為如何將設備路徑傳遞給 <code>lsusb</code> 命令並不容易，但在仔細閲讀手冊頁和初始輸出後，我能夠確定如何構造它。USB 設備駐留在 UDEV 文件系統中。它們的設備路徑始於 USB 設備目錄 <code>/dev/bus/usb/</code>。路徑的其餘部分由設備的總線 ID 和設備 ID 組成。我的無描述設備是 <code>Bus 001 Device 002</code>，被翻譯成了 <code>001/002</code>，完成的路徑為 <code>/dev/bus/usb/001/002</code>。現在我可以把這個路徑傳給 <code>lsusb</code>。我還會用管道傳給 <code>more</code>，因為這裏往往有很多信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb -D /dev/bus/usb/001/002 |more</span></span>
<span class="line"><span>Device: ID 18f8:1486  </span></span>
<span class="line"><span>Device Descriptor:</span></span>
<span class="line"><span>  bLength                18</span></span>
<span class="line"><span>  bDescriptorType         1</span></span>
<span class="line"><span>  bcdUSB               1.10</span></span>
<span class="line"><span>  bDeviceClass            0 (Defined at Interface level)</span></span>
<span class="line"><span>  bDeviceSubClass         0</span></span>
<span class="line"><span>  bDeviceProtocol         0</span></span>
<span class="line"><span>  bMaxPacketSize0         8</span></span>
<span class="line"><span>  idVendor           0x18f8</span></span>
<span class="line"><span>  idProduct          0x1486</span></span>
<span class="line"><span>  bcdDevice            1.00</span></span>
<span class="line"><span>  iManufacturer           0</span></span>
<span class="line"><span>  iProduct                1</span></span>
<span class="line"><span>  iSerial                 0</span></span>
<span class="line"><span>  bNumConfigurations      1</span></span>
<span class="line"><span>  Configuration Descriptor:</span></span>
<span class="line"><span>    bLength                 9</span></span>
<span class="line"><span>    bDescriptorType         2</span></span>
<span class="line"><span>    wTotalLength           59</span></span>
<span class="line"><span>    bNumInterfaces          2</span></span>
<span class="line"><span>    bConfigurationValue     1</span></span>
<span class="line"><span>    iConfiguration          0</span></span>
<span class="line"><span>    bmAttributes         0xa0</span></span>
<span class="line"><span>      (Bus Powered)</span></span>
<span class="line"><span>      Remote Wakeup</span></span>
<span class="line"><span>    MaxPower              100mA</span></span>
<span class="line"><span>    Interface Descriptor:</span></span>
<span class="line"><span>      bLength                 9</span></span>
<span class="line"><span>      bDescriptorType         4</span></span>
<span class="line"><span>      bInterfaceNumber        0</span></span>
<span class="line"><span>      bAlternateSetting       0</span></span>
<span class="line"><span>      bNumEndpoints           1</span></span>
<span class="line"><span>      bInterfaceClass         3 Human Interface Device</span></span>
<span class="line"><span>      bInterfaceSubClass      1 Boot Interface Subclass</span></span>
<span class="line"><span>      bInterfaceProtocol      2 Mouse</span></span>
<span class="line"><span>      iInterface              0</span></span>
<span class="line"><span>        HID Device Descriptor:</span></span></code></pre></div><p>不幸的是，這裏並沒有提供我希望找到的細節。初始輸出中出現的兩個字段 <code>idVendor</code> 和 <code>idProduct</code> 都是空的。這有些幫助，因為往下看一下，就會發現 <code>Mouse</code> 這個詞。所以，這個設備就是我的鼠標。</p><h3 id="usb-id-倉庫" tabindex="-1">USB ID 倉庫 <a class="header-anchor" href="#usb-id-倉庫" aria-label="Permalink to “USB ID 倉庫”">​</a></h3>`,13)),i("p",null,[s[2]||(s[2]=n("這讓我不禁想知道如何才能填充這些字段，不僅是為了自己，也是為了其他 Linux 用户。原來已經有了一個開源項目：",-1)),e(a,{href:"http://www.linux-usb.org/usb-ids.html"},{default:p(()=>[...s[0]||(s[0]=[n("USB ID 倉庫",-1)])]),_:1}),s[3]||(s[3]=n("。它是一個公共倉庫，它包含了 USB 設備中使用的所有已知 ID。它也被用於各種程序中，包括 ",-1)),e(a,{href:"https://sourceforge.net/projects/linux-usb/files/"},{default:p(()=>[...s[1]||(s[1]=[n("USB Utilities",-1)])]),_:1}),s[4]||(s[4]=n("，用於顯示人類可讀的設備名稱。",-1))]),s[21]||(s[21]=l(`<p><img src="https://opensource.com/sites/default/files/uploads/theusbidrepositorysite.png" alt="The USB ID Repository Site" title="The USB ID Repository Site"></p><p>你可以從網站上或通過下載資料庫來瀏覽特定設備的倉庫。也歡迎用户提交新的數據。我要為我的鼠標提交數據，因為它沒有在裏面。</p><h3 id="更新你的-usb-id" tabindex="-1">更新你的 USB ID <a class="header-anchor" href="#更新你的-usb-id" aria-label="Permalink to “更新你的 USB ID”">​</a></h3><p>USB ID 資料庫存儲在一個名為 <code>usb.ids</code> 的文件中。這個文件的位置可能會因 Linux 發行版的不同而不同。</p><p>在 Ubuntu 18.04 中，這個文件位於 <code>/var/lib/usbutils</code>。要更新資料庫，使用命令 <code>update-usbids</code>，你需要用 root 權限或 <code>sudo</code> 來運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo update-usbids</span></span></code></pre></div><p>如果有新文件，它就會被下載。當前的文件將被備份，並被替換為新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -la</span></span>
<span class="line"><span>total 1148</span></span>
<span class="line"><span>drwxr-xr-x  2 root root   4096 Jan 15 00:34 .</span></span>
<span class="line"><span>drwxr-xr-x 85 root root   4096 Nov  7 08:05 ..</span></span>
<span class="line"><span>-rw-r--r--  1 root root 614379 Jan  9 15:34 usb.ids</span></span>
<span class="line"><span>-rw-r--r--  1 root root 551472 Jan 15 00:34 usb.ids.old</span></span></code></pre></div><p>最新版本的 Fedora Linux 將資料庫文件保存在 <code>/usr/share/hwdata</code> 中。而且，沒有更新腳本。而是，資料庫由一個名為 <code>hwdata</code> 的軟件包維護。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf info hwdata</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Installed Packages</span></span>
<span class="line"><span>Name         : hwdata</span></span>
<span class="line"><span>Version      : 0.332</span></span>
<span class="line"><span>Release      : 1.fc31</span></span>
<span class="line"><span>Architecture : noarch</span></span>
<span class="line"><span>Size         : 7.5 M</span></span>
<span class="line"><span>Source       : hwdata-0.332-1.fc31.src.rpm</span></span>
<span class="line"><span>Repository   : @System</span></span>
<span class="line"><span>From repo    : updates</span></span>
<span class="line"><span>Summary      : Hardware identification and configuration data</span></span>
<span class="line"><span>URL          : https://github.com/vcrhonek/hwdata</span></span>
<span class="line"><span>License      : GPLv2+</span></span>
<span class="line"><span>Description  : hwdata contains various hardware identification and configuration data,</span></span>
<span class="line"><span>             : such as the pci.ids and usb.ids databases.</span></span></code></pre></div><p>現在我的 USB 設備列表在這個之前未命名的設備旁邊顯示了一個名字。比較一下上面的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 004: ID 046d:082c Logitech, Inc. HD Webcam C615</span></span>
<span class="line"><span>Bus 001 Device 003: ID 0951:16d2 Kingston Technology</span></span>
<span class="line"><span>Bus 001 Device 014: ID 18f8:1486 [Maxxter]</span></span>
<span class="line"><span>Bus 001 Device 005: ID 051d:0002 American Power Conversion Uninterruptible Power Supply</span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span></code></pre></div><p>你可能會注意到，隨着倉庫定期更新新設備和現有設備的詳細信息，其他設備的描述也會發生變化。</p><h3 id="提交新數據" tabindex="-1">提交新數據 <a class="header-anchor" href="#提交新數據" aria-label="Permalink to “提交新數據”">​</a></h3><p>提交新數據有兩種方式：使用網站或通過電子郵件發送特殊格式的補丁文件。在開始之前，我閲讀了提交指南。首先，我必須註冊一個賬户，然後我需要使用項目的提交系統提供我鼠標的 ID 和名稱。添加任何 USB 設備的過程都是一樣的。</p><p>你使用過 USB ID 倉庫麼？如果有，請在評論中分享你的反饋。</p><hr>`,17)),i("p",null,[s[6]||(s[6]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/20/8/usb-id-repository"},{default:p(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/20/8/usb-id-repository",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/alanfdoss"},{default:p(()=>[...s[7]||(s[7]=[n("Alan Formy-Duval",-1)])]),_:1}),s[12]||(s[12]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:p(()=>[...s[9]||(s[9]=[n("geekpi",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const I=t(c,[["render",u]]);export{x as __pageData,I as default};
